import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface ComicPanel {
  id: number;
  narration: string;
  visualPrompt: string;
  imageUrl?: string;
  speechBubble?: string;
}

export interface ComicStrip {
  title: string;
  originalSummary: string;
  panels: ComicPanel[];
  sourceUrl?: string;
}

export interface ReportSummary {
  incidentDate: string;
  officerName: string;
  allegation: string;
  outcome: string;
  originalText: string;
}

import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { ComicStrip, ReportSummary } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const ASSET_STYLE_PROMPT = "High-resolution sprites, 3D look, semi-realistic rendering, Fantasy setting, similar to Master of Magic, but with more 3D detail.";

export const geminiService = {
  async fetchRandomReport(): Promise<ReportSummary> {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: "Find a specific summary of a real disciplinary action or complaint from the Austin Police Department (APD) documents at austintexas.gov. Focus on a distinct incident. Provide a structured summary including: incident date, the nature of the violation, and the final disciplinary outcome.",
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            incidentDate: { type: Type.STRING },
            officerName: { type: Type.STRING },
            allegation: { type: Type.STRING },
            outcome: { type: Type.STRING },
            originalText: { type: Type.STRING, description: "Detailed description of the incident" },
          },
          required: ["incidentDate", "officerName", "allegation", "outcome", "originalText"]
        }
      }
    });

    try {
      return JSON.parse(response.text.trim());
    } catch (e) {
      console.error("Failed to parse report summary:", e);
      throw new Error("Could not generate a valid report summary.");
    }
  },

  async generateComicScript(report: ReportSummary): Promise<ComicStrip> {
    const prompt = `
      Transform the following real-world police disciplinary report into a 4-panel fantasy comic strip script.
      The setting must be a high-fantasy world (The City of Austin-Gard). 
      The "Police" are the "City Guard". 
      Modern technology like "body cameras" should become "magic scrying stones". 
      "Patrol cars" should become "armored griffins" or "enchanted wagons".

      REPORT SUMMARY:
      Date: ${report.incidentDate}
      Officer: ${report.officerName}
      Incident: ${report.originalText}
      Outcome: ${report.outcome}

      Output a JSON object with a 'title', 'originalSummary', and an array of 4 'panels'.
      Each panel must have:
      - 'narration': The text at the top of the panel.
      - 'visualPrompt': A detailed description for an AI image generator following this style: ${ASSET_STYLE_PROMPT}. 
      - 'speechBubble': Optional dialogue for a character in the panel.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            originalSummary: { type: Type.STRING },
            panels: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.NUMBER },
                  narration: { type: Type.STRING },
                  visualPrompt: { type: Type.STRING },
                  speechBubble: { type: Type.STRING }
                },
                required: ["narration", "visualPrompt"]
              }
            }
          },
          required: ["title", "originalSummary", "panels"]
        }
      }
    });

    return JSON.parse(response.text.trim());
  },

  async generatePanelImage(visualPrompt: string): Promise<string> {
    const fullPrompt = `${visualPrompt} | Style: ${ASSET_STYLE_PROMPT}. 3D rendered, sharp focus, fantasy setting.`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: fullPrompt }]
      },
      config: {
        imageConfig: {
          aspectRatio: "1:1"
        }
      }
    });

    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (part?.inlineData) {
      return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }

    throw new Error("No image data returned from Gemini");
  }
};

import React from 'react';
import { ComicPanel as PanelType } from '../types';

interface ComicPanelProps {
  panel: PanelType;
  index: number;
}

const ComicPanel: React.FC<ComicPanelProps> = ({ panel, index }) => {
