import React, { useState, useEffect } from 'react';

const MESSAGES = [
  "Scouring the archives of the City Guard...",
  "Translating official documents into Elder Runes...",
  "Fetching magical scrying stones for verification...",
  "Drafting the chronicles of discipline...",
  "Consulting the High Wizards of Austin-Gard...",
  "Summoning the art spirits for the panels...",
  "Inking the frames with dragon blood..."
];

const LoadingState: React.FC = () => {
  const [msgIndex, setMsgIndex] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setMsgIndex((prev) => (prev + 1) % MESSAGES.length);
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="flex flex-col items-center justify-center p-12 space-y-8 bg-white comic-border max-w-2xl mx-auto my-12">
      <div className="relative">
        <div className="w-24 h-24 border-8 border-gray-200 border-t-blue-600 rounded-full animate-spin"></div>
        <div className="absolute inset-0 flex items-center justify-center">
          <span className="text-2xl">📜</span>
        </div>
      </div>
      <div className="text-center space-y-2">
        <h2 className="text-3xl font-comic uppercase text-black">Casting Generation Spells</h2>
        <p className="text-lg font-bold text-gray-600 animate-pulse">{MESSAGES[msgIndex]}</p>
      </div>
    </div>
  );
};

export default LoadingState;

import React, { useState, useEffect, useCallback } from 'react';
import { geminiService } from './services/geminiService';
import { ComicStrip } from './types';
import ComicPanel from './components/ComicPanel';
import LoadingState from './components/LoadingState';

const App: React.FC = () => {
  const [comic, setComic] = useState<ComicStrip | null>(null);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const generateComic = useCallback(async () => {
    setLoading(true);
    setError(null);
    setComic(null);

    try {
      // 1. Fetch random report details
      const report = await geminiService.fetchRandomReport();

      // 2. Generate the comic script/story structure
      const script = await geminiService.generateComicScript(report);
      setComic({ ...script, panels: script.panels.map(p => ({ ...p, imageUrl: undefined })) });

      // 3. Generate images for each panel in parallel
      const imagePromises = script.panels.map(async (panel) => {
        const imageUrl = await geminiService.generatePanelImage(panel.visualPrompt);
        return { id: panel.id, imageUrl };
      });

      const images = await Promise.all(imagePromises);

      // 4. Update the state with the images
      setComic(prev => {
        if (!prev) return null;
        return {
          ...prev,
          panels: prev.panels.map(p => {
            const img = images.find(i => i.id === p.id);
            return img ? { ...p, imageUrl: img.imageUrl } : p;
          })
        };
      });

    } catch (err: any) {
      console.error(err);
      setError(err.message || "An unexpected error occurred during generation.");
    } finally {
      setLoading(false);
    }
  }, []);

  return (
    <div className="min-h-screen pb-12">
      {/* Header */}
      <header className="bg-black text-white p-6 shadow-xl sticky top-0 z-50">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-4">
          <div className="text-center md:text-left">
            <h1 className="text-4xl md:text-5xl font-comic uppercase">Austin Guard</h1>
            <p className="text-yellow-400 font-bold text-sm tracking-widest uppercase">Disciplinary Chronicles</p>
          </div>
          <button 
            onClick={generateComic}
            disabled={loading}
            className={`px-8 py-3 rounded-none font-comic text-xl uppercase tracking-wider transition-all
              ${loading 
                ? 'bg-gray-600 cursor-not-allowed' 
                : 'bg-yellow-500 hover:bg-yellow-400 text-black active:translate-y-1 comic-border'
              }`}
          >
            {loading ? 'Generating...' : 'New Random Report'}
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 mt-8">
        {!comic && !loading && !error && (
          <div className="flex flex-col items-center justify-center min-h-[60vh] text-center p-8 bg-white comic-border mt-12">
            <div className="text-8xl mb-6">🛡️</div>
            <h2 className="text-4xl font-comic uppercase mb-4">Official Archives</h2>
            <p className="max-w-lg text-gray-600 font-bold mb-8">
              Every month, the Austin City Guard (APD) publishes reports on the conduct of its knights and guardians. 
              Click above to transform a random disciplinary archive into a visualized fantasy chronicle.
            </p>
            <button 
              onClick={generateComic}
              className="px-12 py-4 bg-black text-white font-comic text-2xl uppercase hover:bg-gray-800 transition-colors"
            >
              Consult the Records
            </button>
          </div>
        )}

        {error && (
          <div className="p-8 bg-red-100 border-4 border-red-500 text-red-700 font-bold max-w-2xl mx-auto mt-12 text-center">
            <h3 className="text-2xl font-comic uppercase mb-2">The Magic Failed!</h3>
            <p className="mb-4">{error}</p>
            <button 
              onClick={generateComic}
              className="px-6 py-2 bg-red-600 text-white font-bold hover:bg-red-700"
            >
              Try Again
            </button>
          </div>
        )}

        {loading && !comic && <LoadingState />}

        {comic && (
          <div className="space-y-8 animate-in fade-in duration-700">
            {/* Strip Intro */}
            <div className="bg-white comic-border p-6 flex flex-col md:flex-row gap-6 items-start">
              <div className="flex-1">
                <h2 className="text-4xl font-comic text-black mb-2 uppercase">{comic.title}</h2>
                <div className="w-24 h-2 bg-yellow-500 mb-4"></div>
                <p className="text-sm font-bold text-gray-500 uppercase mb-2">Original Archive Summary:</p>
                <p className="text-gray-700 italic border-l-4 border-gray-300 pl-4 py-2 bg-gray-50">
                  {comic.originalSummary}
                </p>
              </div>
              <div className="w-full md:w-64 flex flex-col items-center justify-center p-4 bg-gray-100 border-2 border-black border-dashed">
                 <span className="text-4xl mb-2">📜</span>
                 <p className="text-[10px] font-bold text-center text-gray-400 uppercase">
                    Based on official Austin official complaint and discipline documents.
                 </p>
              </div>
            </div>

            {/* The Comic Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              {comic.panels.map((panel, idx) => (
                <ComicPanel key={panel.id || idx} panel={panel} index={idx} />
              ))}
            </div>

            {/* Footer Action */}
            <div className="flex justify-center py-12">
              <button 
                onClick={generateComic}
                disabled={loading}
                className="group flex items-center gap-4 px-10 py-5 bg-black text-white font-comic text-2xl uppercase hover:bg-gray-900 transition-all comic-border"
              >
                <span>Generate Another Chronicle</span>
                <span className="group-hover:translate-x-2 transition-transform">➡️</span>
              </button>
            </div>
          </div>
        )}
      </main>

      {/* Persistent Call-to-Action for Mobile */}
      {comic && !loading && (
        <div className="md:hidden fixed bottom-6 right-6 z-50">
          <button 
            onClick={generateComic}
            className="w-16 h-16 bg-yellow-500 rounded-full flex items-center justify-center shadow-2xl border-4 border-black active:scale-95"
          >
            <span className="text-2xl">⚡</span>
          </button>
        </div>
      )}
    </div>
  );
};

export default App;

