import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { ComicStrip, ReportSummary } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const ASSET_STYLE_PROMPT = "Dramatic modern urban comic art, bold lines, high contrast noir-style lighting, dynamic superhero-comic composition, 3D cell-shaded rendering, realistic urban environments with a gritty superhero aesthetic.";

export const geminiService = {
  async fetchRandomReport(): Promise<ReportSummary> {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: "Search for a specific summary of a real disciplinary action or complaint document from the Austin Police Department (APD) at austintexas.gov. Focus on a clear, documented incident. Provide a structured summary including the incident date, officer name, the specific allegation or violation, and the final disciplinary outcome. Ensure the 'originalText' field contains a detailed chronological account of the incident.",
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            incidentDate: { type: Type.STRING },
            officerName: { type: Type.STRING },
            allegation: { type: Type.STRING },
            outcome: { type: Type.STRING },
            originalText: { type: Type.STRING, description: "Detailed chronological description of the incident events" },
          },
          required: ["incidentDate", "officerName", "allegation", "outcome", "originalText"]
        }
      }
    });

    try {
      return JSON.parse(response.text.trim());
    } catch (e) {
      console.error("Failed to parse report summary:", e);
      throw new Error("Could not generate a valid report summary.");
    }
  },

  async generateComicScript(report: ReportSummary): Promise<ComicStrip> {
    const prompt = `
      Create a 4-panel comic strip script based strictly on the following real-world police disciplinary report.
      While the visual style should be 'Urban Superhero Comic' (dynamic, dramatic, heroic proportions), the narrative and events must remain faithful to the actual facts of the report. 

      REPORT DATA:
      Officer: ${report.officerName}
      Date: ${report.incidentDate}
      Allegation: ${report.allegation}
      Outcome: ${report.outcome}
      Details: ${report.originalText}

      INSTRUCTIONS:
      1. Use real-world terminology (e.g., "Patrol car", "Body worn camera", "Austin Police").
      2. Depict the events chronologically across 4 panels.
      3. The art style should be high-impact comic book art, but the scenes must represent the actual locations (streets of Austin, police headquarters) and actions described.
      4. Ensure the 'speechBubble' reflects either actual quotes from the report or plausible dialogue representing the conflict.

      Output JSON:
      - 'title': A dramatic title for this specific case.
      - 'originalSummary': A concise 1-2 sentence factual summary of the outcome.
      - 'panels': Array of 4 panels with 'id', 'narration', 'visualPrompt', and 'speechBubble'.

      Visual Style Reminder: ${ASSET_STYLE_PROMPT}.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            originalSummary: { type: Type.STRING },
            panels: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.NUMBER },
                  narration: { type: Type.STRING },
                  visualPrompt: { type: Type.STRING },
                  speechBubble: { type: Type.STRING }
                },
                required: ["id", "narration", "visualPrompt"]
              }
            }
          },
          required: ["title", "originalSummary", "panels"]
        }
      }
    });

    return JSON.parse(response.text.trim());
  },

  async generatePanelImage(visualPrompt: string): Promise<string> {
    const fullPrompt = `${visualPrompt} | Style: ${ASSET_STYLE_PROMPT}. Detailed uniforms, cinematic lighting.`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: fullPrompt }]
      },
      config: {
        imageConfig: {
          aspectRatio: "1:1"
        }
      }
    });

    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (part?.inlineData) {
      return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }

    throw new Error("No image data returned from Gemini");
  }
};

