      setComic(prev => {
        if (!prev) return null;
        return {
          ...prev,
          panels: prev.panels.map(p => {
            const img = images.find(i => i.id === p.id);
            return img ? { ...p, imageUrl: img.imageUrl } : p;
          })
        };
      });

    } catch (err: any) {
