      REPORT DATA:
      Officer: ${report.officerName}
      Allegation: ${report.allegation}
      The Incident: ${report.originalText}
      The Consequences: ${report.outcome}

      INSTRUCTIONS:
      1. Use over-the-top comic book language (e.g., 'THE PHANTOM SIREN', 'THE CHRONICLE OF THE COLD BURRITO').
      2. Depict the events across 4 panels:
         - Panel 1: Dramatic introduction of the "Hero" (Officer) in a superhero pose.
         - Panel 2: The "Conflict" (The absurdity/mistake starts).
         - Panel 3: The "Climax" (The mistake reaches its peak absurdity).
         - Panel 4: The "Ironic Justice" (The outcome/suspension).
      3. The 'visualPrompt' should describe superhero action scenes that represent the mundane events (e.g., if he fell asleep, describe him as "Surrendering to the Sandman's Cosmic Grip").

      Output JSON:
      - 'title': A dramatic comic title.
      - 'originalSummary': A brief, ironic 1-sentence summary of the actual facts.
      - 'panels': Array of 4 panels with 'id', 'narration', 'visualPrompt', and 'speechBubble'.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            originalSummary: { type: Type.STRING },
            panels: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.NUMBER },
                  narration: { type: Type.STRING },
                  visualPrompt: { type: Type.STRING },
                  speechBubble: { type: Type.STRING }
                },
                required: ["id", "narration", "visualPrompt"]
              }
            }
          },
          required: ["title", "originalSummary", "panels"]
        }
      }
    });

    const parsed = JSON.parse(response.text.trim());
    return { ...parsed, sourceUrl: report.sourceUrl };
  },

  async generatePanelImage(visualPrompt: string): Promise<string> {
    const ai = getAI();
    const fullPrompt = `${visualPrompt} | Style: ${ASSET_STYLE_PROMPT}`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: fullPrompt }]
      },
      config: {
        imageConfig: {
          aspectRatio: "1:1"
        }
      }
    });

    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (part?.inlineData) {
      return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }

    throw new Error("No image data returned from Gemini");
  }
};

