  async fetchRandomReport(): Promise<ReportSummary> {
    const ai = getAI();
    const seed = Date.now().toString().slice(-6);

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Search the Austin Police Department (APD) document archives at austintexas.gov for a REAL 'Notice of Formal Suspension' or 'Disciplinary Action' PDF. 

      CRITICAL: You must find a specific individual disciplinary case. Use search query randomization: ${seed}.

      Extract the FOLLOWING exactly from the document:
      1. The official name of the officer.
