              >
                {UI_TEXT.LANDING.BUTTON}
              </button>
              {archive.length > 0 && (
                 <button 
                  onClick={() => setIsLockerOpen(true)}
                  className="px-8 py-4 bg-black text-white font-comic text-2xl uppercase hover:bg-gray-900 transition-colors comic-border border-white"
