const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const geminiService = {
  async fetchRandomReport(): Promise<ReportSummary> {
    const ai = getAI();
    const seed = Math.floor(Math.random() * 9999);

    // NOTE: Rule check - Google Search grounding does not support responseMimeType: "application/json".
    // We must request a structured text response instead and parse it manually.
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Find one specific recent Austin Police Department Disciplinary PDF (Notice of Formal Suspension). 
      Search target: "site:austintexas.gov disciplinary suspension ${seed}".

      Extract and list these EXACT fields for ONE specific officer's case:
      OFFICER_NAME: 
      INCIDENT_DATE: 
      ALLEGATION_TYPE: 
      FINAL_OUTCOME: 
      VERBATIM_SUMMARY: (The full description of what they did)
      PDF_URL: (Direct link to the document)`,
      config: {
        tools: [{ googleSearch: {} }],
      }
    });

    const text = response.text || '';
    if (!text || text.length < 20) {
      throw new Error("The archive search returned an empty or insufficient response. Please try again.");
    }

    // Helper to extract fields from the text response
    const extractField = (marker: string) => {
      const regex = new RegExp(`${marker}:?\\s*([\\s\\S]*?)(?=\\n[A-Z_]+:|$)`, 'i');
      const match = text.match(regex);
      return match ? match[1].trim() : 'Unknown';
    };

    const groundingUrl = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.find(c => c.web?.uri?.includes('.pdf'))?.web?.uri 
                        || response.candidates?.[0]?.groundingMetadata?.groundingChunks?.[0]?.web?.uri;

    const report: ReportSummary = {
      officerName: extractField('OFFICER_NAME'),
      incidentDate: extractField('INCIDENT_DATE'),
      allegation: extractField('ALLEGATION_TYPE'),
      outcome: extractField('FINAL_OUTCOME'),
      originalText: extractField('VERBATIM_SUMMARY'),
      sourceUrl: extractField('PDF_URL') !== 'Unknown' ? extractField('PDF_URL') : groundingUrl
    };

    // Verify if sourceUrl is valid and accessible
    if (report.sourceUrl) {
      try {
        const url = new URL(report.sourceUrl);
        if (!['http:', 'https:'].includes(url.protocol)) {
          throw new Error("Invalid protocol");
        }

        // Perform a lightweight check. Since external sites likely block CORS, we use mode: 'no-cors'.
        // This confirms the URL is reachable and well-formed enough for the browser to attempt a request.
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 3000);

        await fetch(report.sourceUrl, { 
          method: 'HEAD', 
          mode: 'no-cors', 
          signal: controller.signal 
        }).finally(() => clearTimeout(timeoutId));
      } catch (err) {
        console.warn(`Source URL verification failed for: ${report.sourceUrl}. The link may be broken or inaccessible. Proceeding without source link.`);
        report.sourceUrl = undefined;
      }
    }

    // Fallback check: If the summary is "Unknown", the extraction failed
    if (report.originalText === 'Unknown') {
       // If standard extraction fails, try a broader grab of the whole text as summary
       report.originalText = text.slice(0, 1000);
    }

    return report;
  },

  async generateComicScript(report: ReportSummary, mode: AppMode): Promise<ComicStrip> {
    const ai = getAI();

    // Using gemini-3-flash-preview for fast text generation with JSON support
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `
        OFFICER: ${report.officerName}
        ALLEGATION: ${report.allegation}
        REPORT SUMMARY: ${report.originalText}
      `,
      config: {
        systemInstruction: AI_INSTRUCTIONS.SCRIPT_SYSTEM(mode),
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            originalSummary: { type: Type.STRING },
            panels: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.NUMBER },
                  narration: { type: Type.STRING },
                  visualPrompt: { type: Type.STRING },
                  speechBubble: { type: Type.STRING }
                },
                required: ["id", "narration", "visualPrompt"]
              }
            }
          },
          required: ["title", "originalSummary", "panels"]
        }
      }
    });

    const text = response.text || '';
    if (!text) throw new Error("Script generation failed to return content.");

    const parsed = JSON.parse(text);
    return { ...parsed, sourceUrl: report.sourceUrl };
  },

  async generatePanelImage(visualPrompt: string, mode: AppMode): Promise<string> {
    const ai = getAI();
    const style = STYLE_PROMPTS[mode];
    const fullPrompt = `${style}: ${visualPrompt}. Simple, funny, exaggerated sketch.`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: fullPrompt }] },
      config: { imageConfig: { aspectRatio: "1:1" } }
    });

    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (part?.inlineData) {
      return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
    throw new Error("No image data returned from Gemini");
  }
};

