          placeholder={UI_TEXT.REPORT_SEARCH.URL_PLACEHOLDER}
          className={`flex-1 p-3 text-sm border-2 ${isGritty ? 'bg-gray-900 border-gray-600 text-white focus:border-red-500' : 'bg-white border-blue-300 text-gray-900 focus:border-blue-700'} focus:outline-none`}
          disabled={isLoadingAny}
          aria-label="Report URL input"
        />
        <button
          onClick={onFetchSpecificReport}
          disabled={isLoadingAny || !manualReportUrl}
          className={`px-6 py-3 font-comic text-lg uppercase tracking-wider ${isLoadingAny ? 'bg-gray-600' : (isGritty ? 'bg-red-600 hover:bg-red-500' : 'bg-blue-600 hover:bg-blue-500')} text-white comic-border border-white`}
        >
          {isFetchingReportUrl && currentLoadingPhase === 'REPORT_SEARCH' ? 'Fetching...' : UI_TEXT.REPORT_SEARCH.FETCH_BUTTON}
        </button>
        <button
          onClick={onGenerateRandomReport}
          disabled={isLoadingAny}
          className={`px-6 py-3 font-comic text-lg uppercase tracking-wider ${isLoadingAny ? 'bg-gray-600' : (isGritty ? 'bg-gray-900 hover:bg-gray-700' : 'bg-gray-700 hover:bg-gray-600')} text-white comic-border border-white`}
        >
          {isFetchingReportUrl && currentLoadingPhase === 'RANDOM_REPORT' ? 'Generating...' : UI_TEXT.REPORT_SEARCH.RANDOM_BUTTON}
        </button>
      </div>

      {/* Error Display for Report Fetch */}
      {error && currentLoadingPhase === 'REPORT_SEARCH' && (
        <div className="p-4 bg-red-700 text-white font-bold mb-4 text-center comic-border">
          <p>{error.message}</p>
        </div>
      )}

      {/* Fetched Report Display */}
      {fetchedReport ? (
        <div className={`comic-border p-4 mt-6 ${isGritty ? 'bg-black text-white border-red-600' : 'bg-white text-gray-900 border-blue-700'}`}>
          <h4 className={`text-xl font-comic uppercase mb-3 ${isGritty ? 'text-red-500' : 'text-blue-700'}`}>{UI_TEXT.REPORT_VIEWER.TITLE}</h4>
          <div className="space-y-2 text-sm font-body">
            <p><strong className={`${isGritty ? 'text-gray-400' : 'text-gray-600'}`}>{UI_TEXT.REPORT_VIEWER.DETAILS_OFFICER}:</strong> {fetchedReport.officerName}</p>
            <p><strong className={`${isGritty ? 'text-gray-400' : 'text-gray-600'}`}>{UI_TEXT.REPORT_VIEWER.DETAILS_DATE}:</strong> {fetchedReport.incidentDate}</p>
            <p><strong className={`${isGritty ? 'text-gray-400' : 'text-gray-600'}`}>{UI_TEXT.REPORT_VIEWER.DETAILS_ALLEGATION}:</strong> {fetchedReport.allegation}</p>
            <p><strong className={`${isGritty ? 'text-gray-400' : 'text-gray-600'}`}>{UI_TEXT.REPORT_VIEWER.DETAILS_OUTCOME}:</strong> {fetchedReport.outcome}</p>
            <div className={`border-l-4 ${isGritty ? 'border-red-600' : 'border-blue-700'} pl-3 py-1 mt-3`}>
              <strong className={`${isGritty ? 'text-gray-400' : 'text-gray-600'}`}>{UI_TEXT.REPORT_VIEWER.DETAILS_SUMMARY}:</strong>
              <p className="mt-1 italic">{fetchedReport.originalText}</p>
            </div>
            {fetchedReport.sourceUrl && (
              <a href={fetchedReport.sourceUrl} target="_blank" rel="noopener noreferrer" 
                 className={`text-[10px] ${isGritty ? 'bg-red-600' : 'bg-blue-600'} text-white px-2 py-0.5 font-bold uppercase hover:opacity-80 inline-block mt-3`}>
                {UI_TEXT.CASE_HEADER.SOURCE_LINK}
              </a>
            )}
          </div>
          <div className="flex justify-between items-center mt-6 pt-4 border-t border-gray-700">
            <button
              onClick={() => onGenerateComicFromReport(fetchedReport)}
              disabled={isGeneratingComic}
              className={`px-6 py-3 font-comic text-lg uppercase tracking-wider ${isGeneratingComic ? 'bg-gray-600' : (isGritty ? 'bg-red-600 hover:bg-red-500' : 'bg-blue-600 hover:bg-blue-500')} text-white comic-border border-white`}
            >
              {isGeneratingComic ? 'Generating Comic...' : UI_TEXT.REPORT_VIEWER.GENERATE_COMIC_BUTTON}
            </button>
            <button
              onClick={onClearReport}
              disabled={isLoadingAny}
              className={`px-4 py-2 font-comic text-sm uppercase ${isGritty ? 'bg-gray-700 hover:bg-gray-600' : 'bg-gray-400 hover:bg-gray-300'} text-white comic-border border-white`}
            >
              {UI_TEXT.REPORT_SEARCH.CLEAR_BUTTON}
            </button>
          </div>
        </div>
      ) : (
        <p className={`text-center py-8 text-lg italic ${isGritty ? 'text-gray-400' : 'text-gray-600'}`}>
          {UI_TEXT.REPORT_SEARCH.NO_REPORT_SELECTED}
        </p>
      )}
    </div>
  );
};

export default ReportInputAndDisplay;

import React, { useState, useCallback, useEffect } from 'react';
import { geminiService } from './services/geminiService';
import { storageService } from './services/storageService';
import { ComicStrip, AppMode, ReportSummary } from './types';
import { UI_TEXT } from './constants/content';
import ComicPanel from './components/ComicPanel';
import LoadingState, { LoadingPhase } from './components/LoadingState';
import ArchiveLocker from './components/ArchiveLocker';
import ReportInputAndDisplay from './components/ReportInputAndDisplay';

const App: React.FC = () => {
  const [comic, setComic] = useState<ComicStrip | null>(null);
  const [isAppInitialized, setIsAppInitialized] = useState<boolean>(false); // Tracks if landing page has been dismissed

  // New states for report search/display workflow
  const [manualReportUrl, setManualReportUrl] = useState<string>('');
  const [fetchedReport, setFetchedReport] = useState<ReportSummary | null>(null);
  const [isFetchingReportUrl, setIsFetchingReportUrl] = useState<boolean>(false); // Loading for URL fetch

  const [isGeneratingComic, setIsGeneratingComic] = useState<boolean>(false); // Loading for comic script + images
  const [currentLoadingPhase, setCurrentLoadingPhase] = useState<LoadingPhase>('INITIAL');

  const [mode, setMode] = useState<AppMode>('gritty');
  const [error, setError] = useState<{ message: string; isQuota?: boolean; isBusy?: boolean } | null>(null);

  const [archive, setArchive] = useState<ComicStrip[]>([]);
  const [isLockerOpen, setIsLockerOpen] = useState<boolean>(false);

  useEffect(() => {
    const loadArchive = async () => {
      const savedComics = await storageService.getAllComics();
      setArchive(savedComics);
    };
    loadArchive();
  }, []);

  const handleOpenKeySelector = async () => {
    if (window.aistudio?.openSelectKey) {
      await window.aistudio.openSelectKey();
      if (error?.isQuota) {
        // If quota error, and they selected a key, try to re-run the last failed action.
        // For simplicity, just reset error for now. User will click retry.
        setError(null); 
      }
    }
  };

  const clearCurrentComic = () => {
    setComic(null);
    setError(null);
    setIsGeneratingComic(false);
    setCurrentLoadingPhase('INITIAL');
  }

  const handleClearReport = () => {
    setFetchedReport(null);
    setManualReportUrl('');
    clearCurrentComic();
  };

  const generateComicStrip = useCallback(async (report: ReportSummary) => {
    setIsGeneratingComic(true);
    setCurrentLoadingPhase('COMIC_GENERATION');
    setError(null);
    setComic(null); // Clear previous comic immediately

    try {
      // Phase 1: Scripting (Fast)
      const script = await geminiService.generateComicScript(report, mode);

      const initialTimestamp = Date.now();
      const initialComic: ComicStrip = { 
        ...script, 
        panels: script.panels.map(p => ({ ...p, imageUrl: undefined })), 
        timestamp: initialTimestamp 
      };

      // Show text IMMEDIATELY
      setComic(initialComic);

      // Phase 2: Parallel Progressive Image Generation
      const updatedPanels = [...initialComic.panels];

      const panelPromises = script.panels.map(async (panel, idx) => {
        try {
          const imageUrl = await geminiService.generatePanelImage(panel.visualPrompt, mode);

          setComic(current => {
            if (!current || current.timestamp !== initialTimestamp) return current; // Ensure we're updating the right comic
            const newPanels = [...current.panels];
            newPanels[idx] = { ...newPanels[idx], imageUrl };
            return { ...current, panels: newPanels };
          });

          updatedPanels[idx] = { ...updatedPanels[idx], imageUrl };
        } catch (imgErr) {
          console.error(`Failed image for panel ${idx}:`, imgErr);
        }
      });

      await Promise.all(panelPromises);

      const finalComic: ComicStrip = {
        ...initialComic,
        panels: updatedPanels
      };

      setComic(current => {
         if (current?.timestamp === initialTimestamp) { // Only save if it's still the active comic
            storageService.saveComic(finalComic).then(() => {
              storageService.getAllComics().then(setArchive);
            });
         }
         return current;
      });

    } catch (err: any) {
      console.error(err);
      const isQuota = err.message?.includes('429') || err.message?.toLowerCase().includes('limit');
      const isBusy = err.message?.includes('503') || err.message?.toLowerCase().includes('demand') || err.message?.toLowerCase().includes('unavailable');

      let errorMessage = err.message || "An unexpected error occurred during comic generation.";
      if (isQuota) errorMessage = UI_TEXT.ERRORS.QUOTA_SUB;
      else if (isBusy) errorMessage = UI_TEXT.ERRORS.BUSY_SUB;

      setError({ 
        message: errorMessage,
        isQuota,
        isBusy
      });
      setComic(null); // Clear any partially generated comic
    } finally {
      setIsGeneratingComic(false);
      setCurrentLoadingPhase('INITIAL');
    }
  }, [mode]);

  const handleGenerateRandomReport = useCallback(async () => {
    clearCurrentComic();
    setFetchedReport(null);
    setIsFetchingReportUrl(true);
    setCurrentLoadingPhase('RANDOM_REPORT');
    setError(null);

    try {
      const report = await geminiService.fetchRandomReport();
      setFetchedReport(report);
      // No automatic comic generation, user decides to click "Generate Comic"
    } catch (err: any) {
      console.error(err);
      const isQuota = err.message?.includes('429') || err.message?.toLowerCase().includes('limit');
      const isBusy = err.message?.includes('503') || err.message?.toLowerCase().includes('demand') || err.message?.toLowerCase().includes('unavailable');

      let errorMessage = err.message || "An unexpected error occurred while fetching the random report.";
      if (isQuota) errorMessage = UI_TEXT.ERRORS.QUOTA_SUB;
      else if (isBusy) errorMessage = UI_TEXT.ERRORS.BUSY_SUB;

      setError({ 
        message: errorMessage,
        isQuota,
        isBusy
      });
    } finally {
      setIsFetchingReportUrl(false);
      setCurrentLoadingPhase('INITIAL');
    }
  }, [mode]);

  const handleFetchSpecificReport = useCallback(async () => {
    clearCurrentComic();
    setFetchedReport(null);
    setIsFetchingReportUrl(true);
    setCurrentLoadingPhase('REPORT_SEARCH');
    setError(null);

    if (!manualReportUrl.trim()) {
      setError({ message: "Please enter a URL to fetch a report." });
      setIsFetchingReportUrl(false);
      setCurrentLoadingPhase('INITIAL');
      return;
    }

    try {
      const report = await geminiService.fetchSpecificReport(manualReportUrl);
      setFetchedReport(report);
    } catch (err: any) {
      console.error(err);
      const isQuota = err.message?.includes('429') || err.message?.toLowerCase().includes('limit');
      const isBusy = err.message?.includes('503') || err.message?.toLowerCase().includes('demand') || err.message?.toLowerCase().includes('unavailable');

      let errorMessage = err.message || `An unexpected error occurred while fetching report from ${manualReportUrl}.`;
      if (isQuota) errorMessage = UI_TEXT.ERRORS.QUOTA_SUB;
      else if (isBusy) errorMessage = UI_TEXT.ERRORS.BUSY_SUB;

      setError({ 
        message: errorMessage,
        isQuota,
        isBusy
      });
    } finally {
      setIsFetchingReportUrl(false);
      setCurrentLoadingPhase('INITIAL');
    }
  }, [manualReportUrl]);

  const selectArchivedComic = (selected: ComicStrip) => {
    setComic(selected);
    setFetchedReport(null); // Clear any fetched report when viewing archive
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // Determine global loading state for disabling buttons
  const isLoadingAny = isFetchingReportUrl || isGeneratingComic;

  return (
    <div className={`min-h-screen pb-12 transition-colors duration-500 ${mode === 'superhero' ? 'bg-yellow-50' : 'bg-gray-100'}`}>
      <header className="bg-black text-white p-6 shadow-xl border-b-4 border-red-600 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-6">
          <div className="text-center md:text-left">
            <h1 className="text-3xl md:text-4xl font-comic uppercase italic tracking-tighter leading-none">{UI_TEXT.TITLE}</h1>
            <p className="text-red-500 font-bold text-xs tracking-[0.2em] uppercase mt-1">{UI_TEXT.SUBTITLE}</p>
          </div>

          <div className="flex flex-wrap items-center justify-center gap-6">
            <div className="flex bg-gray-800 p-1 comic-border border-white border-2">
              <button onClick={() => setMode('gritty')} className={`px-4 py-1 text-xs font-bold uppercase ${mode === 'gritty' ? 'bg-white text-black' : 'text-gray-400'}`}>Gritty Noir</button>
              <button onClick={() => setMode('superhero')} className={`px-4 py-1 text-xs font-bold uppercase ${mode === 'superhero' ? 'bg-red-600 text-white' : 'text-gray-400'}`}>Heroic Fail</button>
            </div>

            <button onClick={() => setIsLockerOpen(true)} className="flex items-center gap-2 px-4 py-2 bg-gray-900 border-2 border-white hover:bg-gray-800 relative group" disabled={isLoadingAny}>
              <span className="text-xl">🗄️</span>
              <span className="text-[10px] font-bold uppercase hidden md:inline">{UI_TEXT.BUTTONS.VIEW_LOCKER}</span>
              {archive.length > 0 && (
                <span className="absolute -top-2 -right-2 bg-red-600 text-white text-[10px] w-5 h-5 rounded-full flex items-center justify-center border border-white font-bold">
                  {archive.length}
                </span>
              )}
            </button>

            <button onClick={handleOpenKeySelector} className="p-2 hover:bg-gray-800 rounded-full" disabled={isLoadingAny}><span className="text-2xl">🔑</span></button>

            {/* The "Access New Case" button is now only for initiating the first view */}
            {!isAppInitialized && (
              <button 
                onClick={() => setIsAppInitialized(true)}
                className={`px-8 py-3 font-comic text-xl uppercase tracking-wider bg-red-600 hover:bg-red-500 text-white comic-border border-white`}
              >
                {UI_TEXT.BUTTONS.NEW_CASE}
              </button>
            )}
          </div>
        </div>
      </header>

      <ArchiveLocker isOpen={isLockerOpen} onClose={() => setIsLockerOpen(false)} comics={archive} onSelect={selectArchivedComic} />

      <main className="max-w-7xl mx-auto px-4 mt-8">
        {!isAppInitialized && (
          <div className="flex flex-col items-center justify-center min-h-[60vh] text-center p-8 bg-white comic-border mt-12 relative overflow-hidden">
            <div className="text-8xl mb-6">{mode === 'gritty' ? '📁' : '🦸‍♂️'}</div>
            <h2 className="text-4xl font-comic uppercase mb-4 italic">{mode === 'gritty' ? UI_TEXT.LANDING.GRITTY.TITLE : UI_TEXT.LANDING.SUPERHERO.TITLE}</h2>
            <div className="max-w-xl text-gray-700 font-bold mb-8">
              {mode === 'gritty' ? UI_TEXT.LANDING.GRITTY.DESCRIPTION : UI_TEXT.LANDING.SUPERHERO.DESCRIPTION}
            </div>
            <div className="flex gap-4">
              <button onClick={() => setIsAppInitialized(true)} className="px-12 py-4 bg-red-600 text-white font-comic text-2xl uppercase hover:bg-red-700 comic-border border-white">{UI_TEXT.LANDING.BUTTON}</button>
              {archive.length > 0 && <button onClick={() => setIsLockerOpen(true)} className="px-8 py-4 bg-black text-white font-comic text-2xl uppercase hover:bg-gray-900 comic-border border-white">History</button>}
            </div>
          </div>
        )}

        {isAppInitialized && (
          <>
            <ReportInputAndDisplay
              mode={mode}
              manualReportUrl={manualReportUrl}
              setManualReportUrl={setManualReportUrl}
              fetchedReport={fetchedReport}
              onFetchSpecificReport={handleFetchSpecificReport}
              onGenerateRandomReport={handleGenerateRandomReport}
              onClearReport={handleClearReport}
              onGenerateComicFromReport={generateComicStrip}
              isFetchingReportUrl={isFetchingReportUrl}
              isGeneratingComic={isGeneratingComic}
              error={error}
              currentLoadingPhase={currentLoadingPhase}
            />

            {error && !isFetchingReportUrl && !isGeneratingComic && (
              <div className="p-8 bg-red-100 border-4 border-red-600 text-red-700 font-bold max-w-2xl mx-auto mt-12 text-center shadow-lg">
                <h3 className="text-2xl font-comic uppercase mb-2">
                  {error.isQuota ? UI_TEXT.ERRORS.QUOTA_TITLE : (error.isBusy ? UI_TEXT.ERRORS.BUSY_TITLE : UI_TEXT.ERRORS.GENERAL_TITLE)}
                </h3>
                <p className="mb-4">{error.message}</p>
                <button onClick={() => setError(null)} className="px-6 py-2 bg-red-600 text-white font-bold comic-border">{UI_TEXT.BUTTONS.RETRY}</button>
              </div>
            )}

            {(isFetchingReportUrl || isGeneratingComic) && (
              <LoadingState phase={currentLoadingPhase} />
            )}

            {comic && (
              <div key={comic.timestamp || 'current'} className="space-y-8 animate-swipe mt-8">
                <div className={`comic-border p-6 flex flex-col md:flex-row gap-6 items-start ${mode === 'superhero' ? 'bg-red-50' : 'bg-white'}`}>
                  <div className="flex-1">
                    <div className="flex items-center gap-3 mb-2">
                      <div className={`h-10 w-2 ${mode === 'superhero' ? 'bg-yellow-500' : 'bg-red-600'}`}></div>
                      <h2 className="text-4xl font-comic text-black uppercase italic">{comic.title}</h2>
                    </div>

                    {comic.timestamp && archive.some(a => a.timestamp === comic.timestamp) && (
                      <div className="mb-2">
                        <span className="text-[9px] font-bold bg-green-600 text-white px-2 py-0.5 uppercase tracking-widest comic-border border-[1px]">{UI_TEXT.CASE_HEADER.ARCHIVED_BADGE}</span>
                      </div>
                    )}

                    <div className="flex flex-col md:flex-row md:items-center gap-4 mb-2">
                      <p className="text-sm font-bold text-gray-400 uppercase">{mode === 'gritty' ? UI_TEXT.CASE_HEADER.GRITTY : UI_TEXT.CASE_HEADER.SUPERHERO}</p>
                      {comic.sourceUrl && (
                        <a href={comic.sourceUrl} target="_blank" rel="noopener noreferrer" className="text-[10px] bg-black text-white px-2 py-0.5 font-bold uppercase hover:bg-red-600">
                          {UI_TEXT.CASE_HEADER.SOURCE_LINK}
                        </a>
                      )}
                    </div>
                    <p className="text-gray-800 font-body border-l-4 border-black pl-4 py-2 bg-gray-50 italic">{comic.originalSummary}</p>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  {comic.panels.map((panel, idx) => (
                    <ComicPanel key={`${comic.timestamp}-${panel.id}`} panel={panel} index={idx} />
                  ))}
                </div>

                {!isGeneratingComic && (
                  <div className="flex justify-center py-12 gap-6">
                    <button onClick={() => setIsLockerOpen(true)} className="px-8 py-5 bg-white text-black font-comic text-2xl uppercase hover:bg-gray-100 comic-border">Archive</button>
                    <button onClick={() => handleGenerateRandomReport().then(r => r && generateComicStrip(r))} disabled={isLoadingAny} className="group flex items-center gap-4 px-10 py-5 bg-black text-white font-comic text-2xl uppercase hover:bg-gray-900 comic-border">
                      <span>{UI_TEXT.BUTTONS.NEXT_CASE}</span>
                      <span className="group-hover:translate-x-2 transition-transform text-red-500">{mode === 'superhero' ? '🦸‍♂️' : '⚖️'}</span>
                    </button>
                  </div>
                )}
              </div>
            )}
          </>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect } from 'react';
import { geminiService } from './services/geminiService';
import { storageService } from './services/storageService';
import { ComicStrip, AppMode, ReportSummary } from './types';
import { UI_TEXT } from './constants/content';
import ComicPanel from './components/ComicPanel';
import LoadingState, { LoadingPhase } from './components/LoadingState';
import ArchiveLocker from './components/ArchiveLocker';
import ReportInputAndDisplay from './components/ReportInputAndDisplay';

const App: React.FC = () => {
  const [comic, setComic] = useState<ComicStrip | null>(null);
  const [isAppInitialized, setIsAppInitialized] = useState<boolean>(false); // Tracks if landing page has been dismissed

  // New states for report search/display workflow
  const [manualReportUrl, setManualReportUrl] = useState<string>('');
  const [fetchedReport, setFetchedReport] = useState<ReportSummary | null>(null);
  const [isFetchingReportUrl, setIsFetchingReportUrl] = useState<boolean>(false); // Loading for URL fetch

  const [isGeneratingComic, setIsGeneratingComic] = useState<boolean>(false); // Loading for comic script + images
  const [currentLoadingPhase, setCurrentLoadingPhase] = useState<LoadingPhase>('INITIAL');

  const [mode, setMode] = useState<AppMode>('gritty');
  const [error, setError] = useState<{ message: string; isQuota?: boolean; isBusy?: boolean } | null>(null);

  const [archive, setArchive] = useState<ComicStrip[]>([]);
  const [isLockerOpen, setIsLockerOpen] = useState<boolean>(false);

  useEffect(() => {
    const loadArchive = async () => {
      const savedComics = await storageService.getAllComics();
      setArchive(savedComics);
    };
    loadArchive();
  }, []);

  const handleOpenKeySelector = async () => {
    if (window.aistudio?.openSelectKey) {
      await window.aistudio.openSelectKey();
      if (error?.isQuota) {
        // If quota error, and they selected a key, try to re-run the last failed action.
        // For simplicity, just reset error for now. User will click retry.
        setError(null); 
      }
    }
  };

  const clearCurrentComic = () => {
    setComic(null);
    setError(null);
    setIsGeneratingComic(false);
    setCurrentLoadingPhase('INITIAL');
  }

  const handleClearReport = () => {
    setFetchedReport(null);
    setManualReportUrl('');
    clearCurrentComic();
  };

  const generateComicStrip = useCallback(async (report: ReportSummary) => {
    setIsGeneratingComic(true);
    setCurrentLoadingPhase('COMIC_GENERATION');
    setError(null);
    setComic(null); // Clear previous comic immediately

    try {
      // Phase 1: Scripting (Fast)
      const script = await geminiService.generateComicScript(report, mode);

      const initialTimestamp = Date.now();
      const initialComic: ComicStrip = { 
        ...script, 
        panels: script.panels.map(p => ({ ...p, imageUrl: undefined })), 
        timestamp: initialTimestamp 
      };

      // Show text IMMEDIATELY
      setComic(initialComic);

      // Phase 2: Parallel Progressive Image Generation
      const updatedPanels = [...initialComic.panels];

      const panelPromises = script.panels.map(async (panel, idx) => {
        try {
          const imageUrl = await geminiService.generatePanelImage(panel.visualPrompt, mode);

          setComic(current => {
            if (!current || current.timestamp !== initialTimestamp) return current; // Ensure we're updating the right comic
            const newPanels = [...current.panels];
            newPanels[idx] = { ...newPanels[idx], imageUrl };
            return { ...current, panels: newPanels };
          });

          updatedPanels[idx] = { ...updatedPanels[idx], imageUrl };
        } catch (imgErr) {
          console.error(`Failed image for panel ${idx}:`, imgErr);
        }
      });

      await Promise.all(panelPromises);

      const finalComic: ComicStrip = {
        ...initialComic,
        panels: updatedPanels
      };

      setComic(current => {
         if (current?.timestamp === initialTimestamp) { // Only save if it's still the active comic
            storageService.saveComic(finalComic).then(() => {
              storageService.getAllComics().then(setArchive);
            });
         }
         return current;
      });

    } catch (err: any) {
      console.error(err);
      const isQuota = err.message?.includes('429') || err.message?.toLowerCase().includes('limit');
      const isBusy = err.message?.includes('503') || err.message?.toLowerCase().includes('demand') || err.message?.toLowerCase().includes('unavailable');

      let errorMessage = err.message || "An unexpected error occurred during comic generation.";
      if (isQuota) errorMessage = UI_TEXT.ERRORS.QUOTA_SUB;
      else if (isBusy) errorMessage = UI_TEXT.ERRORS.BUSY_SUB;

      setError({ 
        message: errorMessage,
        isQuota,
        isBusy
      });
      setComic(null); // Clear any partially generated comic
    } finally {
      setIsGeneratingComic(false);
      setCurrentLoadingPhase('INITIAL');
    }
  }, [mode]);

  // Changed handleGenerateRandomReport to return the fetched report (or null)
  const handleGenerateRandomReport = useCallback(async (): Promise<ReportSummary | null> => {
    clearCurrentComic();
    setFetchedReport(null);
    setIsFetchingReportUrl(true);
    setCurrentLoadingPhase('RANDOM_REPORT');
    setError(null);

    try {
      const report = await geminiService.fetchRandomReport();
      setFetchedReport(report);
      return report; // Return the fetched report
    } catch (err: any) {
      console.error(err);
      const isQuota = err.message?.includes('429') || err.message?.toLowerCase().includes('limit');
      const isBusy = err.message?.includes('503') || err.message?.toLowerCase().includes('demand') || err.message?.toLowerCase().includes('unavailable');

      let errorMessage = err.message || "An unexpected error occurred while fetching the random report.";
      if (isQuota) errorMessage = UI_TEXT.ERRORS.QUOTA_SUB;
      else if (isBusy) errorMessage = UI_TEXT.ERRORS.BUSY_SUB;

      setError({ 
        message: errorMessage,
        isQuota,
        isBusy
      });
      return null; // Return null on error
    } finally {
      setIsFetchingReportUrl(false);
      setCurrentLoadingPhase('INITIAL');
    }
  }, [mode]);

  const handleFetchSpecificReport = useCallback(async () => {
    clearCurrentComic();
    setFetchedReport(null);
    setIsFetchingReportUrl(true);
    setCurrentLoadingPhase('REPORT_SEARCH');
    setError(null);

    if (!manualReportUrl.trim()) {
      setError({ message: "Please enter a URL to fetch a report." });
      setIsFetchingReportUrl(false);
      setCurrentLoadingPhase('INITIAL');
      return;
    }

    try {
      const report = await geminiService.fetchSpecificReport(manualReportUrl);
      setFetchedReport(report);
    } catch (err: any) {
      console.error(err);
      const isQuota = err.message?.includes('429') || err.message?.toLowerCase().includes('limit');
      const isBusy = err.message?.includes('503') || err.message?.toLowerCase().includes('demand') || err.message?.toLowerCase().includes('unavailable');

      let errorMessage = err.message || `An unexpected error occurred while fetching report from ${manualReportUrl}.`;
      if (isQuota) errorMessage = UI_TEXT.ERRORS.QUOTA_SUB;
      else if (isBusy) errorMessage = UI_TEXT.ERRORS.BUSY_SUB;

      setError({ 
        message: errorMessage,
        isQuota,
        isBusy
      });
    } finally {
      setIsFetchingReportUrl(false);
      setCurrentLoadingPhase('INITIAL');
    }
  }, [manualReportUrl]);

  const selectArchivedComic = (selected: ComicStrip) => {
    setComic(selected);
    setFetchedReport(null); // Clear any fetched report when viewing archive
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // Determine global loading state for disabling buttons
  const isLoadingAny = isFetchingReportUrl || isGeneratingComic;

  return (
