  mode,
  availableReports,
  selectedReport,
  onSelectReport,
  onBackToList,
  onFetchNewReportList,
  onGenerateComicFromReport,
  isFetchingReportList,
  isGeneratingComic,
  error,
  currentLoadingPhase
