  const generateComicStrip = useCallback(async (report: ReportSummary) => {
    setIsGeneratingComic(true);
    setCurrentLoadingPhase('COMIC_GENERATION');
    setError(null);
    setComic(null); // Clear previous comic immediately

    try {
      // Phase 1: Scripting (Fast)
      const script = await geminiService.generateComicScript(report, mode);

      const initialTimestamp = Date.now();
      const initialComic: ComicStrip = { 
        ...script, 
        panels: script.panels.map(p => ({ ...p, imageUrl: undefined })), 
        timestamp: initialTimestamp 
      };

      // Show text IMMEDIATELY
      setComic(initialComic);

      // Phase 2: Parallel Progressive Image Generation
      const updatedPanels = [...initialComic.panels];

      const panelPromises = script.panels.map(async (panel, idx) => {
        try {
          const imageUrl = await geminiService.generatePanelImage(panel.visualPrompt, mode);

          setComic(current => {
            if (!current || current.timestamp !== initialTimestamp) return current; // Ensure we're updating the right comic
            const newPanels = [...current.panels];
            newPanels[idx] = { ...newPanels[idx], imageUrl };
            return { ...current, panels: newPanels };
          });

          updatedPanels[idx] = { ...updatedPanels[idx], imageUrl };
        } catch (imgErr) {
          console.error(`Failed image for panel ${idx}:`, imgErr);
        }
      });

      await Promise.all(panelPromises);

      const finalComic: ComicStrip = {
        ...initialComic,
        panels: updatedPanels
      };

      setComic(current => {
         if (current?.timestamp === initialTimestamp) { // Only save if it's still the active comic
            storageService.saveComic(finalComic).then(() => {
              storageService.getAllComics().then(setArchive);
            });
         }
         return current;
      });

    } catch (err: any) {
      console.error(err);
      const isQuota = err.message?.includes('429') || err.message?.toLowerCase().includes('limit');
      const isBusy = err.message?.includes('503') || err.message?.toLowerCase().includes('demand') || err.message?.toLowerCase().includes('unavailable');

      let errorMessage = err.message || "An unexpected error occurred during comic generation.";
      if (isQuota) errorMessage = UI_TEXT.ERRORS.QUOTA_SUB;
      else if (isBusy) errorMessage = UI_TEXT.ERRORS.BUSY_SUB;

      setError({ 
        message: errorMessage,
        isQuota,
        isBusy
      });
      setComic(null); // Clear any partially generated comic
    } finally {
      setIsGeneratingComic(false);
      setCurrentLoadingPhase('INITIAL');
    }
  }, [mode]);

  const handleGenerateReportList = useCallback(async () => {
    clearCurrentComic();
    setAvailableReports(null); // Clear previous list
    setSelectedReport(null);
    setIsFetchingReportList(true);
    setCurrentLoadingPhase('REPORT_LIST_FETCH');
    setError(null);

    try {
      const reports = await geminiService.fetchRandomReportList(20); // Fetch ~20 reports
      setAvailableReports(reports);

      if (reports.length === 0) {
        // If no reports were successfully fetched, set an error
        setError({
          message: "Could not fetch any new reports. The AI may be busy or unable to find suitable documents. Please try again.",
          isBusy: true // Treat as busy for UI messaging
        });
      }

    } catch (err: any) {
      console.error(err);
      const isQuota = err.message?.includes('429') || err.message?.toLowerCase().includes('limit');
      const isBusy = err.message?.includes('503') || err.message?.toLowerCase().includes('demand') || err.message?.toLowerCase().includes('unavailable');

      let errorMessage = err.message || "An unexpected error occurred while fetching the report list.";
      if (isQuota) errorMessage = UI_TEXT.ERRORS.QUOTA_SUB;
      else if (isBusy) errorMessage = UI_TEXT.ERRORS.BUSY_SUB;

      setError({ 
        message: errorMessage,
        isQuota,
        isBusy
      });
    } finally {
      setIsFetchingReportList(false);
      setCurrentLoadingPhase('INITIAL');
    }
  }, []);

  const handleSelectReport = useCallback((report: ReportSummary) => {
    setSelectedReport(report);
    clearCurrentComic(); // Clear any existing comic if a new report is selected
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, []);

  const selectArchivedComic = (selected: ComicStrip) => {
    setComic(selected);
    setAvailableReports(null); // Clear list when viewing archive
    setSelectedReport(null); // Clear selected report when viewing archive
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // Determine global loading state for disabling buttons
  const isLoadingAny = isFetchingReportList || isGeneratingComic;

  return (
    <div className={`min-h-screen pb-12 transition-colors duration-500 ${mode === 'superhero' ? 'bg-yellow-50' : 'bg-gray-100'}`}>
      <header className="bg-black text-white p-6 shadow-xl border-b-4 border-red-600 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-6">
          <div className="text-center md:text-left">
            <h1 className="text-3xl md:text-4xl font-comic uppercase italic tracking-tighter leading-none">{UI_TEXT.TITLE}</h1>
            <p className="text-red-500 font-bold text-xs tracking-[0.2em] uppercase mt-1">{UI_TEXT.SUBTITLE}</p>
          </div>

          <div className="flex flex-wrap items-center justify-center gap-6">
            <div className="flex bg-gray-800 p-1 comic-border border-white border-2">
