import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { ComicStrip, ReportSummary, AppMode } from "../types";
import { AI_INSTRUCTIONS, STYLE_PROMPTS } from "../constants/content";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

/**
 * Utility to wrap API calls with exponential backoff for transient errors (503, 429)
 */
async function callWithRetry<T>(fn: () => Promise<T>, maxRetries = 3): Promise<T> {
  let lastError: any;
  for (let i = 0; i < maxRetries; i++) {
    try {
      return await fn();
    } catch (err: any) {
      lastError = err;
      // Extract status code if available, otherwise look for markers in message
      const status = err.status || 
                    (err.message?.includes('503') ? 503 : 
                    (err.message?.includes('429') ? 429 : 0));

      if (status === 503 || status === 429) {
        console.warn(`Gemini API busy (${status}). Retry attempt ${i + 1}/${maxRetries}...`);
        const delay = Math.pow(2, i) * 1500 + Math.random() * 1000;
        await new Promise(resolve => setTimeout(resolve, delay));
        continue;
      }
      throw err;
    }
  }
  throw lastError;
}

export const geminiService = {
  /**
   * Fetches a single random disciplinary report.
   * This is an internal helper for `fetchRandomReportList`.
   */
  private_fetchSingleRandomReport: async (): Promise<ReportSummary> => {
    const ai = getAI();
    const seed = Math.floor(Math.random() * 1000000);

    const searchQueries = [
      'site:austintexas.gov "Notice of Formal Suspension" APD disciplinary',
      'site:austintexas.gov "Memorandum" Austin Police Department disciplinary',
      'site:austintexas.gov "Internal Affairs" Austin Police disciplinary',
      'site:austintexas.gov APD "indefinite suspension" notice'
    ];
    const selectedQuery = searchQueries[seed % searchQueries.length];

    // Primary attempt to extract structured data
    let text = '';
    // Fix: Declare 'response' outside the try block so it's accessible later for groundingChunk extraction.
    let response: GenerateContentResponse | null = null;
    try {
      const generatedResponse = await callWithRetry(() => ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Find a specific, recent Austin Police Department disciplinary document. 
        Use this search query: ${selectedQuery}
        Focus on finding a PDF document from the AustinTexas.gov domain.

        From ONE specific case found in the search results, extract:
        OFFICER_NAME: (Full name of the officer involved)
        INCIDENT_DATE: (The date of the misconduct, in YYYY-MM-DD or Month Day, Year format)
        ALLEGATION_TYPE: (The type of policy violation or incident, e.g., 'Use of Force', 'Conduct')
        FINAL_OUTCOME: (The official disciplinary action taken, e.g., '3-day suspension', 'Indefinite Suspension')
        VERBATIM_SUMMARY: (A detailed, objective summary of the incident as reported in the document. Prioritize factual reporting over brevity, aim for 200-300 words. DO NOT invent details.)
        PDF_URL: (The direct URL to the source PDF document. Must be from austintexas.gov)`,
        config: {
          tools: [{ googleSearch: {} }],
        }
      }));
      response = generatedResponse; // Assign the result to the outer-scoped variable
      text = response.text || '';
    } catch (e) {
      console.warn("Initial structured extraction failed:", e);
    }

    // Fallback if initial structured extraction is insufficient
    if (!text || text.length < 100 || !text.includes('OFFICER_NAME') || !text.includes('VERBATIM_SUMMARY')) {
       const chunks = (text ? null : undefined) || // Only use chunks if text was empty or very short
                      (await callWithRetry(() => ai.models.generateContent({
                        model: 'gemini-3-flash-preview',
                        contents: `Find a specific, recent Austin Police Department disciplinary document. 
                        Use this search query: ${selectedQuery}
                        Focus on finding a PDF document from the AustinTexas.gov domain.`,
                        config: {
                          tools: [{ googleSearch: {} }],
                        }
                      }))).candidates?.[0]?.groundingMetadata?.groundingChunks;

       const topLink = chunks?.find(c => c.web?.uri?.includes('.pdf'))?.web?.uri || chunks?.[0]?.web?.uri;

       if (topLink) {
          console.log(`Falling back to summary extraction for URL: ${topLink}`);
          const fallbackResponse = await callWithRetry(() => ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Read the document at this URL: ${topLink}. Provide a detailed, objective summary of the disciplinary incident, including the officer's name, incident date, allegation type, and final outcome. Format it as:
            OFFICER_NAME: [Name]
            INCIDENT_DATE: [Date]
            ALLEGATION_TYPE: [Type]
            FINAL_OUTCOME: [Outcome]
            VERBATIM_SUMMARY: [Detailed summary of what happened, 200-300 words.]
            PDF_URL: ${topLink}`,
            config: {
              tools: [{ googleSearch: {} }],
            }
          }));
          text = fallbackResponse.text || '';
       }
    }

    if (!text || text.length < 50) { // Increased threshold for a valid response
      throw new Error("The search engine found results but failed to extract the report details. Please try again to trigger a different search path.");
    }

    const extractField = (marker: string, fallback: string = 'Unknown') => {
      // Adjusted regex to be more robust for multi-line summaries and ending with PDF_URL
      const regex = new RegExp(`${marker}[:\\s]*([\\s\\S]*?)(?=(?:\\n[A-Z_]+[:\\s])|$)`, 'i');
      const match = text.match(regex);
      return match && match[1].trim().length > 0 ? match[1].trim() : fallback;
    };

    // Fix: 'response' is now correctly scoped and typed.
    const groundingUrl = text.includes('PDF_URL:') ? extractField('PDF_URL') : 
                         (response?.candidates?.[0]?.groundingMetadata?.groundingChunks?.find(c => c.web?.uri?.includes('.pdf'))?.web?.uri 
                         || response?.candidates?.[0]?.groundingMetadata?.groundingChunks?.[0]?.web?.uri);

    const report: ReportSummary = {
      officerName: extractField('OFFICER_NAME'),
      incidentDate: extractField('INCIDENT_DATE'),
      allegation: extractField('ALLEGATION_TYPE'),
      outcome: extractField('FINAL_OUTCOME'),
      originalText: extractField('VERBATIM_SUMMARY'),
      sourceUrl: groundingUrl !== 'Unknown' ? groundingUrl : undefined
    };

    if (report.originalText === 'Unknown' || report.originalText.length < 100) { // Ensure a substantial summary
       if (text.length > 200) { // If raw text is long enough, use it as a fallback summary
          report.originalText = text;
       } else {
          throw new Error("Could not find enough detail in the report to generate a comic. Please try again.");
       }
    }

    // Validate the sourceUrl (if it's not undefined)
    if (report.sourceUrl) {
      try {
        const url = new URL(report.sourceUrl);
        if (!['http:', 'https:'].includes(url.protocol)) {
          report.sourceUrl = undefined; // Invalid protocol
        } else {
          // Attempt a quick head request to check if it's reachable (no-cors prevents blocking)
          const controller = new AbortController();
          const timeoutId = setTimeout(() => controller.abort(), 2000); // Shorter timeout
          await fetch(report.sourceUrl, { 
            method: 'HEAD', 
            mode: 'no-cors', 
            signal: controller.signal 
          }).catch(() => { report.sourceUrl = undefined; /* Mark as unreachable */ })
            .finally(() => clearTimeout(timeoutId));
        }
      } catch (err) {
        report.sourceUrl = undefined; // Malformed URL
      }
    }


    return report;
  },

  /**
   * Fetches a list of random disciplinary reports.
   * Calls `private_fetchSingleRandomReport` multiple times in parallel.
   */
  async fetchRandomReportList(count: number = 20): Promise<ReportSummary[]> {
    const reportPromises: Promise<ReportSummary | null>[] = Array.from({ length: count }).map(async (_, index) => {
      try {
        return await this.private_fetchSingleRandomReport();
      } catch (error) {
        // Log individual failures but don't rethrow to allow other fetches to complete
        console.warn(`Failed to fetch a single random report (attempt ${index + 1}):`, error);
        return null; // Return null for failed fetches
      }
    });

    const results = await Promise.all(reportPromises);
    // Filter out any nulls from failed fetches
    return results.filter((report): report is ReportSummary => report !== null);
  },

  async generateComicScript(report: ReportSummary, mode: AppMode): Promise<ComicStrip> {
    const ai = getAI();

    const response = await callWithRetry(() => ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `
        OFFICER: ${report.officerName}
        ALLEGATION: ${report.allegation}
        REPORT SUMMARY: ${report.originalText}
      `,
      config: {
        systemInstruction: AI_INSTRUCTIONS.SCRIPT_SYSTEM(mode),
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            originalSummary: { type: Type.STRING },
            panels: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.NUMBER },
                  narration: { type: Type.STRING },
                  visualPrompt: { type: Type.STRING },
                  speechBubble: { type: Type.STRING }
                },
                required: ["id", "narration", "visualPrompt"]
              }
            }
          },
          required: ["title", "originalSummary", "panels"]
        }
      }
    }));

    const text = response.text || '';
    if (!text) throw new Error("Script generation failed to return content.");

    const parsed = JSON.parse(text);
    return { ...parsed, sourceUrl: report.sourceUrl };
  },

  async generatePanelImage(visualPrompt: string, mode: AppMode): Promise<string> {
    const ai = getAI();
    const style = STYLE_PROMPTS[mode];
    // The visualPrompt generated by the script model should already be styled.
    // Prepending the style and removing conflicting generic descriptors.
    const fullPrompt = `${style}: ${visualPrompt}`;

    const response = await callWithRetry(() => ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: fullPrompt }] },
      config: { imageConfig: { aspectRatio: "1:1" } }
    }));

    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (part?.inlineData) {
      return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
    throw new Error("No image data returned from Gemini");
  }
};

