import { GoogleGenAI, Type } from "@google/genai";
import { ComicStrip, ReportSummary, AppMode } from "../types";
import { AI_INSTRUCTIONS, STYLE_PROMPTS, HARDCODED_REPORTS } from "../constants/content";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

/**
 * Utility to wrap API calls with exponential backoff for transient errors (503, 429)
 */
async function callWithRetry<T>(fn: () => Promise<T>, maxRetries = 3): Promise<T> {
  let lastError: any;
  for (let i = 0; i < maxRetries; i++) {
    try {
      return await fn();
    } catch (err: any) {
      lastError = err;
      // Extract status code if available, otherwise look for markers in message
      const status = err.status || 
                    (err.message?.includes('503') ? 503 : 
                    (err.message?.includes('429') ? 429 : 0));

      if (status === 503 || status === 429) {
        console.warn(`Gemini API busy (${status}). Retry attempt ${i + 1}/${maxRetries}...`);
        const delay = Math.pow(2, i) * 1500 + Math.random() * 1000;
        await new Promise(resolve => setTimeout(resolve, delay));
        continue;
      }
      throw err;
    }
  }
  throw lastError;
}

export const geminiService = {
  /**
   * Fetches a list of random disciplinary reports from a hardcoded, pre-processed set.
   * This simulates a backend fetching mechanism for stability and performance.
   */
  async fetchRandomReportList(count: number = 20): Promise<ReportSummary[]> {
    // Simulate network delay
    await new Promise(resolve => setTimeout(resolve, 500 + Math.random() * 1000));

    // Shuffle the hardcoded reports to get a "random" selection
    const shuffledReports = [...HARDCODED_REPORTS].sort(() => 0.5 - Math.random());

    // Return a subset of the shuffled reports
    return shuffledReports.slice(0, count);
  },

  async generateComicScript(report: ReportSummary, mode: AppMode): Promise<ComicStrip> {
    const ai = getAI();

    const response = await callWithRetry(() => ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `
        OFFICER: ${report.officerName}
        ALLEGATION: ${report.allegation}
        REPORT SUMMARY: ${report.originalText}
      `,
      config: {
        systemInstruction: AI_INSTRUCTIONS.SCRIPT_SYSTEM(mode),
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            originalSummary: { type: Type.STRING },
            panels: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.NUMBER },
                  narration: { type: Type.STRING },
                  visualPrompt: { type: Type.STRING },
                  speechBubble: { type: Type.STRING }
                },
                required: ["id", "narration", "visualPrompt"]
              }
            }
          },
          required: ["title", "originalSummary", "panels"]
        }
      }
    }));

    const text = response.text || '';
    if (!text) throw new Error("Script generation failed to return content.");

    const parsed = JSON.parse(text);
    return { ...parsed, sourceUrl: report.sourceUrl };
  },

  async generatePanelImage(visualPrompt: string, mode: AppMode): Promise<string> {
    const ai = getAI();
    const style = STYLE_PROMPTS[mode];
    // The visualPrompt generated by the script model should already be styled.
    // Prepending the style and removing conflicting generic descriptors.
    const fullPrompt = `${style}: ${visualPrompt}`;

    const response = await callWithRetry(() => ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: fullPrompt }] },
      config: { imageConfig: { aspectRatio: "1:1" } }
    }));

    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (part?.inlineData) {
      return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
    throw new Error("No image data returned from Gemini");
  }
};

import React, { useState, useEffect } from 'react';
import { LOADING_MESSAGES } from '../constants/content';

export type LoadingPhase = keyof typeof LOADING_MESSAGES;

interface LoadingStateProps {
  phase: LoadingPhase;
}

const LoadingState: React.FC<LoadingStateProps> = ({ phase }) => {
  const [msgIndex, setMsgIndex] = useState(0);

  const currentMessages = LOADING_MESSAGES[phase] || LOADING_MESSAGES.INITIAL;

  useEffect(() => {
    setMsgIndex(0); // Reset index when phase changes
    const interval = setInterval(() => {
      setMsgIndex((prev) => (prev + 1) % currentMessages.length);
    }, 4000);
    return () => clearInterval(interval);
  }, [phase, currentMessages.length]);

  return (
    <div className="flex flex-col items-center justify-center p-12 space-y-8 bg-white comic-border max-w-2xl mx-auto my-12">
      <div className="relative">
        <div className="w-24 h-24 border-8 border-black border-t-red-600 rounded-full animate-spin"></div>
        <div className="absolute inset-0 flex items-center justify-center">
          <span className="text-3xl">⚖️</span>
        </div>
      </div>
      <div className="text-center space-y-2 min-h-[100px] flex flex-col justify-center items-center">
        <h2 className="text-2xl font-comic uppercase text-black tracking-widest">
          {phase === 'REPORT_LIST_FETCH' && "Loading Curated Reports..."}
          {phase === 'COMIC_GENERATION' && "Generating Comic Strip..."}
          {phase === 'INITIAL' && "Loading Application..."}
        </h2>
        <div key={msgIndex} className="inline-block overflow-hidden max-w-full">
          <p className="text-sm font-bold text-gray-500 uppercase tracking-tight">
            {currentMessages[msgIndex]}
          </p>
        </div>
      </div>
    </div>
  );
};

export default LoadingState;

