const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

/**
 * Utility to wrap API calls with exponential backoff for transient errors (503, 429)
 */
async function callWithRetry<T>(fn: () => Promise<T>, maxRetries = 3): Promise<T> {
  let lastError: any;
  for (let i = 0; i < maxRetries; i++) {
    try {
      return await fn();
    } catch (err: any) {
      lastError = err;
      // Extract status code if available, otherwise look for markers in message
      const status = err.status || 
                    (err.message?.includes('503') ? 503 : 
                    (err.message?.includes('429') ? 429 : 0));

      if (status === 503 || status === 429) {
        console.warn(`Gemini API busy (${status}). Retry attempt ${i + 1}/${maxRetries}...`);
        const delay = Math.pow(2, i) * 1500 + Math.random() * 1000;
        await new Promise(resolve => setTimeout(resolve, delay));
        continue;
      }
      throw err;
    }
  }
  throw lastError;
}

export const geminiService = {
  /**
   * Fetches a single random disciplinary report using Google Search grounding.
   */
  private_fetchSingleRandomReport: async (): Promise<ReportSummary> => {
    const ai = getAI();
    const seed = Math.floor(Math.random() * 1000000).toString(); // Use a string for the prompt

    // Explicitly type the response to GenerateContentResponse
    const response: GenerateContentResponse = await callWithRetry(() => ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: AI_INSTRUCTIONS.SEARCH_PROMPT(seed), // Use the specific search prompt
      config: {
        tools: [{ googleSearch: {} }],
      }
    }));

    const text = response.text || '';
    if (!text || text.length < 50) { // Ensure a minimum length for a valid response
      throw new Error("The search engine found results but failed to extract coherent report details. Please try again.");
    }

    const extractField = (marker: string, fallback: string = 'Unknown') => {
      // Regex to capture content between a marker and the next marker or end of string
      const regex = new RegExp(`${marker}:\\s*([\\s\\S]*?)(?=(?:\\n[A-Z_]+:|\\Z))`, 'i');
      const match = text.match(regex);
      return match && match[1].trim().length > 0 ? match[1].trim() : fallback;
    };

    // Extract all fields using the defined markers
    const officerName = extractField('OFFICER_NAME');
    const incidentDate = extractField('INCIDENT_DATE');
    const allegation = extractField('ALLEGATION_TYPE');
    const outcome = extractField('FINAL_OUTCOME');
    const originalText = extractField('ORIGINAL_TEXT');
    let sourceUrl = extractField('SOURCE_URL');

    // Fallback for sourceUrl if not explicitly extracted in text, use grounding chunks
    if (sourceUrl === 'Unknown' || !sourceUrl.startsWith('http')) {
        const groundingChunk = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.find(c => c.web?.uri?.includes('austintexas.gov') && c.web?.uri?.includes('.pdf'));
        if (groundingChunk?.web?.uri) {
            sourceUrl = groundingChunk.web.uri;
        } else if (response.candidates?.[0]?.groundingMetadata?.groundingChunks?.[0]?.web?.uri) {
            // Take the first available web URI as a last resort if it looks like a URL
            sourceUrl = response.candidates[0].groundingMetadata.groundingChunks[0].web.uri;
        }
    }

    const report: ReportSummary = {
      officerName,
      incidentDate,
      allegation,
      outcome,
      originalText,
      sourceUrl: sourceUrl !== 'Unknown' && sourceUrl.startsWith('http') ? sourceUrl : undefined,
    };

    // Basic validation to ensure a meaningful report
    if (report.originalText === 'Unknown' || report.originalText.length < 100) {
      throw new Error("Could not extract a sufficient summary from the report. Please try again.");
    }

    return report;
  },

  /**
   * Fetches a list of random disciplinary reports by calling private_fetchSingleRandomReport multiple times.
   */
  async fetchRandomReportList(count: number = 20): Promise<ReportSummary[]> {
    const reportPromises: Promise<ReportSummary | null>[] = Array.from({ length: count }).map(async (_, index) => {
      try {
        return await this.private_fetchSingleRandomReport();
      } catch (error) {
        console.warn(`Failed to fetch a single random report (attempt ${index + 1}):`, error);
        return null; // Return null for failed fetches to allow others to complete
      }
    });

    const results = await Promise.all(reportPromises);
    // Filter out any nulls from failed fetches
    return results.filter((report): report is ReportSummary => report !== null);
  },

  async generateComicScript(report: ReportSummary, mode: AppMode): Promise<ComicStrip> {
    const ai = getAI();

    const response: GenerateContentResponse = await callWithRetry(() => ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `
        OFFICER: ${report.officerName}
        ALLEGATION: ${report.allegation}
        REPORT SUMMARY: ${report.originalText}
      `,
      config: {
        systemInstruction: AI_INSTRUCTIONS.SCRIPT_SYSTEM(mode),
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            originalSummary: { type: Type.STRING },
            panels: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.NUMBER },
                  narration: { type: Type.STRING },
                  visualPrompt: { type: Type.STRING },
                  speechBubble: { type: Type.STRING }
                },
                required: ["id", "narration", "visualPrompt"]
              }
            }
          },
          required: ["title", "originalSummary", "panels"]
        }
      }
    }));

    const text = response.text || '';
    if (!text) throw new Error("Script generation failed to return content.");

    const parsed = JSON.parse(text);
    return { ...parsed, sourceUrl: report.sourceUrl };
  },

  async generatePanelImage(visualPrompt: string, mode: AppMode): Promise<string> {
    const ai = getAI();
    const style = STYLE_PROMPTS[mode];
    const fullPrompt = `${style}: ${visualPrompt}`;

    const response: GenerateContentResponse = await callWithRetry(() => ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: fullPrompt }] },
      config: { imageConfig: { aspectRatio: "1:1" } }
    }));

    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (part?.inlineData) {
      return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
    throw new Error("No image data returned from Gemini");
  }
};

