const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

/**
 * Utility to wrap API calls with exponential backoff for transient errors (503, 429)
 */
async function callWithRetry<T>(fn: () => Promise<T>, maxRetries = 3): Promise<T> {
  let lastError: any;
  for (let i = 0; i < maxRetries; i++) {
    try {
      return await fn();
    } catch (err: any) {
      lastError = err;
      // Extract status code if available, otherwise look for markers in message
      const status = err.status || 
                    (err.message?.includes('503') ? 503 : 
                    (err.message?.includes('429') ? 429 : 0));

      if (status === 503 || status === 429) {
        console.warn(`Gemini API busy (${status}). Retry attempt ${i + 1}/${maxRetries}...`);
        const delay = Math.pow(2, i) * 1500 + Math.random() * 1000;
        await new Promise(resolve => setTimeout(resolve, delay));
        continue;
      }
      throw err;
    }
  }
  throw lastError;
}

export const geminiService = {
  /**
   * Discovers a list of potential PDF report URLs using Google Search grounding.
   */
  async discoverReportUrls(): Promise<ReportSummary[]> {
    const ai = getAI();
    const seed = Math.floor(Math.random() * 1000000).toString();

    const response: GenerateContentResponse = await callWithRetry(() => ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: AI_INSTRUCTIONS.DISCOVERY_PROMPT(seed),
      config: {
        tools: [{ googleSearch: {} }],
      }
    }));

    const text = response.text || '';
    if (!text || text.length < 20) {
      throw new Error("AI failed to discover any PDF links. The search may have yielded no direct PDF results, or the model could not parse them.");
    }

    // Attempt to parse URLs from the raw text. Expecting one URL per line.
    const rawUrls = text.split('\n')
                        .map(line => line.trim())
                        .filter(line => line.startsWith('http') && line.endsWith('.pdf'));

    const uniqueUrls = Array.from(new Set(rawUrls)); // Ensure unique URLs

    const reports: ReportSummary[] = uniqueUrls.map(url => ({
      incidentDate: 'Unknown',
      officerName: 'Unknown',
      allegation: 'Unknown',
      outcome: 'Unknown',
      originalText: 'Click to load details', // Placeholder text
      sourceUrl: url,
    }));

    if (reports.length === 0) {
      throw new Error("AI discovered links, but none were valid PDF URLs from austintexas.gov. Please try again.");
    }

    return reports;
  },

  /**
   * Extracts detailed information from a specific report URL using Google Search grounding.
   */
  async extractReportDetailsFromUrl(url: string): Promise<ReportSummary> {
    const ai = getAI();

    const response: GenerateContentResponse = await callWithRetry(() => ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: AI_INSTRUCTIONS.EXTRACTION_PROMPT(url),
      config: {
        tools: [{ googleSearch: {} }],
      }
    }));

    const text = response.text || '';
    if (!text || text.length < 100) { // Ensure a minimum length for a valid response
      throw new Error(`AI failed to extract sufficient details from ${url}. The document might be unreadable or empty.`);
    }

    const extractField = (marker: string, fallback: string = 'Unknown') => {
      const regex = new RegExp(`${marker}:\\s*([\\s\\S]*?)(?=(?:\\n[A-Z_]+:|\\Z))`, 'i');
      const match = text.match(regex);
      return match && match[1].trim().length > 0 ? match[1].trim() : fallback;
    };

    const officerName = extractField('OFFICER_NAME');
    const incidentDate = extractField('INCIDENT_DATE');
    const allegation = extractField('ALLEGATION_TYPE');
    const outcome = extractField('FINAL_OUTCOME');
    const originalText = extractField('ORIGINAL_TEXT');
    const sourceUrl = extractField('SOURCE_URL', url); // Use the provided URL as fallback

    const report: ReportSummary = {
      officerName,
      incidentDate,
      allegation,
      outcome,
      originalText,
      sourceUrl: sourceUrl.startsWith('http') ? sourceUrl : url, // Ensure a valid URL
    };

    if (report.originalText === 'Unknown' || report.originalText.length < 100) {
      throw new Error(`Could not extract a sufficient summary from the document at ${url}.`);
    }

    return report;
  },

  /**
   * Fetches a list of random disciplinary reports (by discovering URLs).
   * This is the initial discovery phase.
   */
  async fetchRandomReportList(): Promise<ReportSummary[]> {
    // This now directly calls the discovery function
    return this.discoverReportUrls();
  },

  async generateComicScript(report: ReportSummary, mode: AppMode): Promise<ComicStrip> {
    const ai = getAI();

    const response: GenerateContentResponse = await callWithRetry(() => ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `
        OFFICER: ${report.officerName}
        ALLEGATION: ${report.allegation}
        REPORT SUMMARY: ${report.originalText}
      `,
      config: {
        systemInstruction: AI_INSTRUCTIONS.SCRIPT_SYSTEM(mode),
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            originalSummary: { type: Type.STRING },
            panels: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.NUMBER },
                  narration: { type: Type.STRING },
                  visualPrompt: { type: Type.STRING },
                  speechBubble: { type: Type.STRING }
                },
                required: ["id", "narration", "visualPrompt"]
              }
            }
          },
          required: ["title", "originalSummary", "panels"]
        }
      }
    }));

    const text = response.text || '';
    if (!text) throw new Error("Script generation failed to return content.");

    const parsed = JSON.parse(text);
    return { ...parsed, sourceUrl: report.sourceUrl };
  },

  async generatePanelImage(visualPrompt: string, mode: AppMode): Promise<string> {
    const ai = getAI();
    const style = STYLE_PROMPTS[mode];
    const fullPrompt = `${style}: ${visualPrompt}`;

    const response: GenerateContentResponse = await callWithRetry(() => ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: fullPrompt }] },
      config: { imageConfig: { aspectRatio: "1:1" } }
    }));

    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (part?.inlineData) {
      return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
    throw new Error("No image data returned from Gemini");
  }
};

import { ComicStrip, ReportSummary } from "../types";

const DB_NAME = 'APD_Archive_DB';
const STORE_NAME_COMICS = 'case_files'; // Renamed for clarity
const STORE_NAME_DISCOVERED_REPORTS = 'discovered_reports'; // New store for discovered URLs
const DB_VERSION = 2; // Increment DB version due to new store
const MAX_ARCHIVE_SIZE = 20;
const CACHE_NAME = 'apd-comic-images-v1';

/**
 * Utility to convert base64 data strings to Blobs for efficient storage/caching
 */
const base64ToBlob = (base64: string): Blob => {
  const [header, data] = base64.split(',');
  const mime = header.match(/:(.*?);/)?.[1] || 'image/png';
  const binary = atob(data);
  const array = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    array[i] = binary.charCodeAt(i);
  }
  return new Blob([array], { type: mime });
};

export const storageService = {
  async initDB(): Promise<IDBDatabase> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);
      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        if (!db.objectStoreNames.contains(STORE_NAME_COMICS)) {
          db.createObjectStore(STORE_NAME_COMICS, { keyPath: 'timestamp' });
        }
        if (!db.objectStoreNames.contains(STORE_NAME_DISCOVERED_REPORTS)) {
          db.createObjectStore(STORE_NAME_DISCOVERED_REPORTS, { keyPath: 'sourceUrl' }); // Key by URL
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  },

  /**
   * Caches a generated image in the browser's persistent Cache Storage.
   * Returns a synthetic URL that can be used as an <img> src.
   */
  async cacheImage(id: string, base64Data: string): Promise<string> {
    try {
      const cache = await caches.open(CACHE_NAME);
      const blob = base64ToBlob(base64Data);
      const response = new Response(blob, {
        headers: { 'Content-Type': blob.type, 'Cache-Control': 'public, max-age=31536000' }
      });
      // We use a synthetic URL for the cache key
      const syntheticUrl = `https://apd-archives.local/images/${id}`;
      await cache.put(syntheticUrl, response);
      return syntheticUrl;
    } catch (e) {
      console.error("Failed to cache image:", e);
      return base64Data; // Fallback to base64 if cache fails
    }
  },

  /**
   * Cleans up images in the cache that are no longer referenced in the DB.
   */
  async pruneImageCache(validUrls: Set<string>): Promise<void> {
    const cache = await caches.open(CACHE_NAME);
    const keys = await cache.keys();
    for (const request of keys) {
      if (!validUrls.has(request.url)) {
        await cache.delete(request);
      }
    }
  },

  async saveComic(comic: ComicStrip): Promise<void> {
    const db = await this.initDB();

    // 1. Process and cache images before saving metadata to DB
    const processedPanels = await Promise.all(comic.panels.map(async (panel, idx) => {
      if (panel.imageUrl && panel.imageUrl.startsWith('data:')) {
        const cacheId = `${comic.timestamp || Date.now()}-p${idx}`;
        const cachedUrl = await this.cacheImage(cacheId, panel.imageUrl);
        return { ...panel, imageUrl: cachedUrl };
      }
      return panel;
    }));

    const comicToSave = { ...comic, panels: processedPanels, timestamp: comic.timestamp || Date.now() };

    const tx = db.transaction(STORE_NAME_COMICS, 'readwrite');
    const store = tx.objectStore(STORE_NAME_COMICS);
    store.add(comicToSave);

    // 2. Maintain limit of 20 and prune orphaned images
    return new Promise((resolve) => {
      tx.oncomplete = async () => {
        const allComics = await this.getAllComics();
        if (allComics.length > MAX_ARCHIVE_SIZE) {
          const toDelete = allComics.slice(MAX_ARCHIVE_SIZE);
          const deleteTx = db.transaction(STORE_NAME_COMICS, 'readwrite');
          const deleteStore = deleteTx.objectStore(STORE_NAME_COMICS);
          toDelete.forEach(c => deleteStore.delete(c.timestamp!));
        }

        // Gather all current valid image URLs to prune the cache
        const currentComics = await this.getAllComics();
        const validUrls = new Set<string>();
        currentComics.forEach(c => c.panels.forEach(p => {
          if (p.imageUrl) validUrls.add(p.imageUrl);
        }));
        await this.pruneImageCache(validUrls);

        resolve();
      };
    });
  },

  async getAllComics(): Promise<ComicStrip[]> {
    const db = await this.initDB();
    const tx = db.transaction(STORE_NAME_COMICS, 'readonly');
    const store = tx.objectStore(STORE_NAME_COMICS);
    const request = store.getAll();

    return new Promise((resolve) => {
      request.onsuccess = () => {
        const results = request.result || [];
        resolve(results.sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0)));
      };
    });
  },

  async saveDiscoveredReports(reports: ReportSummary[]): Promise<void> {
    const db = await this.initDB();
    const tx = db.transaction(STORE_NAME_DISCOVERED_REPORTS, 'readwrite');
    const store = tx.objectStore(STORE_NAME_DISCOVERED_REPORTS);
    reports.forEach(report => {
        if (report.sourceUrl) {
            store.put(report); // Use put to update if already exists
        }
    });
    return new Promise(resolve => {
        tx.oncomplete = () => resolve();
        tx.onerror = () => console.error("Error saving discovered reports:", tx.error);
    });
  },

  async getDiscoveredReports(): Promise<ReportSummary[]> {
    const db = await this.initDB();
    const tx = db.transaction(STORE_NAME_DISCOVERED_REPORTS, 'readonly');
    const store = tx.objectStore(STORE_NAME_DISCOVERED_REPORTS);
    const request = store.getAll();

    return new Promise((resolve) => {
      request.onsuccess = () => {
        resolve(request.result || []);
      };
    });
  },

  async clearArchive(): Promise<void> {
    const db = await this.initDB();
    const comicTx = db.transaction(STORE_NAME_COMICS, 'readwrite');
    comicTx.objectStore(STORE_NAME_COMICS).clear();

    const discoveredTx = db.transaction(STORE_NAME_DISCOVERED_REPORTS, 'readwrite');
    discoveredTx.objectStore(STORE_NAME_DISCOVERED_REPORTS).clear();

    await caches.delete(CACHE_NAME);
  }
};

import React, { useState, useEffect } from 'react';
import { LOADING_MESSAGES } from '../constants/content';

export type LoadingPhase = keyof typeof LOADING_MESSAGES;

interface LoadingStateProps {
  phase: LoadingPhase;
}

const LoadingState: React.FC<LoadingStateProps> = ({ phase }) => {
  const [msgIndex, setMsgIndex] = useState(0);

  const currentMessages = LOADING_MESSAGES[phase] || LOADING_MESSAGES.INITIAL;

  useEffect(() => {
    setMsgIndex(0); // Reset index when phase changes
    const interval = setInterval(() => {
      setMsgIndex((prev) => (prev + 1) % currentMessages.length);
    }, 4000);
    return () => clearInterval(interval);
  }, [phase, currentMessages.length]);

  return (
    <div className="flex flex-col items-center justify-center p-12 space-y-8 bg-white comic-border max-w-2xl mx-auto my-12">
      <div className="relative">
        <div className="w-24 h-24 border-8 border-black border-t-red-600 rounded-full animate-spin"></div>
        <div className="absolute inset-0 flex items-center justify-center">
          <span className="text-3xl">⚖️</span>
        </div>
      </div>
      <div className="text-center space-y-2 min-h-[100px] flex flex-col justify-center items-center">
        <h2 className="text-2xl font-comic uppercase text-black tracking-widest">
          {phase === 'REPORT_LIST_FETCH' && "Discovering Public Records..."}
          {phase === 'REPORT_DETAIL_FETCH' && "Analyzing Document..."} {/* New text */}
          {phase === 'COMIC_GENERATION' && "Generating Comic Strip..."}
          {phase === 'INITIAL' && "Loading Application..."}
        </h2>
        <div key={msgIndex} className="inline-block overflow-hidden max-w-full">
          <p className="text-sm font-bold text-gray-500 uppercase tracking-tight">
            {currentMessages[msgIndex]}
          </p>
        </div>
      </div>
    </div>
  );
};

export default LoadingState;

import React, { useState, useCallback, useEffect } from 'react';
import { geminiService } from './services/geminiService';
import { storageService } from './services/storageService';
import { ComicStrip, AppMode, ReportSummary } from './types';
import { UI_TEXT } from './constants/content';
import ComicPanel from './components/ComicPanel';
import LoadingState, { LoadingPhase } from './components/LoadingState';
import ArchiveLocker from './components/ArchiveLocker';
import ReportListAndDetail from './components/ReportListAndDetail';

const App: React.FC = () => {
  const [comic, setComic] = useState<ComicStrip | null>(null);
  const [isAppInitialized, setIsAppInitialized] = useState<boolean>(false);

  const [availableReports, setAvailableReports] = useState<ReportSummary[] | null>(null);
  const [selectedReport, setSelectedReport] = useState<ReportSummary | null>(null);
  const [isFetchingReportList, setIsFetchingReportList] = useState<boolean>(false);
  const [isFetchingReportDetails, setIsFetchingReportDetails] = useState<boolean>(false); // New state for detail fetching

  const [isGeneratingComic, setIsGeneratingComic] = useState<boolean>(false);
  const [currentLoadingPhase, setCurrentLoadingPhase] = useState<LoadingPhase>('INITIAL');

  const [mode, setMode] = useState<AppMode>('gritty');
  const [error, setError] = useState<{ message: string; isQuota?: boolean; isBusy?: boolean } | null>(null);

  const [archive, setArchive] = useState<ComicStrip[]>([]);
  const [isLockerOpen, setIsLockerOpen] = useState<boolean>(false);

  useEffect(() => {
    const loadData = async () => {
      const savedComics = await storageService.getAllComics();
      setArchive(savedComics);
      const savedDiscoveredReports = await storageService.getDiscoveredReports();
      setAvailableReports(savedDiscoveredReports);
    };
    loadData();
  }, []);

  const handleOpenKeySelector = async () => {
    if (window.aistudio?.openSelectKey) {
      await window.aistudio.openSelectKey();
      if (error?.isQuota) {
        setError(null); 
      }
    }
  };

  const clearCurrentComic = () => {
    setComic(null);
    setError(null);
    setIsGeneratingComic(false);
    setCurrentLoadingPhase('INITIAL');
  }

  const handleBackToList = () => {
    setSelectedReport(null);
    clearCurrentComic();
  };

  const generateComicStrip = useCallback(async (report: ReportSummary) => {
    if (!report || report.originalText === 'Click to load details') {
      setError({ message: "Please load the report details before generating a comic.", isBusy: false });
      return;
    }

    setIsGeneratingComic(true);
    setCurrentLoadingPhase('COMIC_GENERATION');
    setError(null);
    setComic(null);

    try {
      const script = await geminiService.generateComicScript(report, mode);

      const initialTimestamp = Date.now();
      const initialComic: ComicStrip = { 
        ...script, 
        panels: script.panels.map(p => ({ ...p, imageUrl: undefined })), 
        timestamp: initialTimestamp 
      };

      setComic(initialComic);

      const updatedPanels = [...initialComic.panels];

      const panelPromises = script.panels.map(async (panel, idx) => {
        try {
          const imageUrl = await geminiService.generatePanelImage(panel.visualPrompt, mode);

          setComic(current => {
            if (!current || current.timestamp !== initialTimestamp) return current;
            const newPanels = [...current.panels];
            newPanels[idx] = { ...newPanels[idx], imageUrl };
            return { ...current, panels: newPanels };
          });

          updatedPanels[idx] = { ...updatedPanels[idx], imageUrl };
        } catch (imgErr) {
          console.error(`Failed image for panel ${idx}:`, imgErr);
        }
      });

      await Promise.all(panelPromises);

      const finalComic: ComicStrip = {
        ...initialComic,
        panels: updatedPanels
      };

      setComic(current => {
         if (current?.timestamp === initialTimestamp) {
            storageService.saveComic(finalComic).then(() => {
              storageService.getAllComics().then(setArchive);
            });
         }
         return current;
      });

    } catch (err: any) {
      console.error(err);
      const isQuota = err.message?.includes('429') || err.message?.toLowerCase().includes('limit');
      const isBusy = err.message?.includes('503') || err.message?.toLowerCase().includes('demand') || err.message?.toLowerCase().includes('unavailable');

      let errorMessage = err.message || "An unexpected error occurred during comic generation.";
      if (isQuota) errorMessage = UI_TEXT.ERRORS.QUOTA_SUB;
      else if (isBusy) errorMessage = UI_TEXT.ERRORS.BUSY_SUB;

      setError({ 
        message: errorMessage,
        isQuota,
        isBusy
      });
      setComic(null);
    } finally {
      setIsGeneratingComic(false);
      setCurrentLoadingPhase('INITIAL');
    }
  }, [mode]);

  const handleGenerateReportList = useCallback(async () => {
    clearCurrentComic();
    setAvailableReports(null);
    setSelectedReport(null);
    setIsFetchingReportList(true);
    setCurrentLoadingPhase('REPORT_LIST_FETCH');
    setError(null);

    try {
      const discoveredReports = await geminiService.discoverReportUrls();
      await storageService.saveDiscoveredReports(discoveredReports); // Persist the discovered URLs
      setAvailableReports(discoveredReports);

      if (discoveredReports.length === 0) {
        setError({
          message: "Could not discover any new report links. The AI may be busy or unable to find suitable PDF documents. Please try again.",
          isBusy: true
        });
      }

    } catch (err: any) {
      console.error(err);
      const isQuota = err.message?.includes('429') || err.message?.toLowerCase().includes('limit');
      const isBusy = err.message?.includes('503') || err.message?.toLowerCase().includes('demand') || err.message?.toLowerCase().includes('unavailable');

      let errorMessage = err.message || "An unexpected error occurred while fetching the report list.";
      if (isQuota) errorMessage = UI_TEXT.ERRORS.QUOTA_SUB;
      else if (isBusy) errorMessage = UI_TEXT.ERRORS.BUSY_SUB;

      setError({ 
        message: errorMessage,
        isQuota,
        isBusy
      });
    } finally {
      setIsFetchingReportList(false);
      setCurrentLoadingPhase('INITIAL');
    }
  }, []);

  const handleLoadReportDetails = useCallback(async (report: ReportSummary) => {
    clearCurrentComic();
    setSelectedReport(null); // Clear previous selection while loading
    setIsFetchingReportDetails(true);
    setCurrentLoadingPhase('REPORT_DETAIL_FETCH');
    setError(null);

    try {
      const detailedReport = await geminiService.extractReportDetailsFromUrl(report.sourceUrl!);
      await storageService.saveDiscoveredReports([detailedReport]); // Update with full details
      setSelectedReport(detailedReport);
    } catch (err: any) {
      console.error(err);
      const isQuota = err.message?.includes('429') || err.message?.toLowerCase().includes('limit');
      const isBusy = err.message?.includes('503') || err.message?.toLowerCase().includes('demand') || err.message?.toLowerCase().includes('unavailable');

      let errorMessage = err.message || "An unexpected error occurred while fetching report details.";
      if (isQuota) errorMessage = UI_TEXT.ERRORS.QUOTA_SUB;
      else if (isBusy) errorMessage = UI_TEXT.ERRORS.BUSY_SUB;

      setError({ 
        message: errorMessage,
        isQuota,
        isBusy
      });
    } finally {
      setIsFetchingReportDetails(false);
      setCurrentLoadingPhase('INITIAL');
    }
  }, []);

  const handleSelectReport = useCallback((report: ReportSummary) => {
    // If report already has full details, just select it.
    // Otherwise, trigger loading details.
    if (report.originalText !== 'Click to load details') {
      setSelectedReport(report);
      clearCurrentComic();
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } else {
      handleLoadReportDetails(report);
    }
  }, [handleLoadReportDetails]);

  const selectArchivedComic = (selected: ComicStrip) => {
    setComic(selected);
    setAvailableReports(null);
    setSelectedReport(null);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // Determine global loading state for disabling buttons
  const isLoadingAny = isFetchingReportList || isGeneratingComic || isFetchingReportDetails;

  return (
    <div className={`min-h-screen pb-12 transition-colors duration-500 ${mode === 'superhero' ? 'bg-yellow-50' : 'bg-gray-100'}`}>
      <header className="bg-black text-white p-6 shadow-xl border-b-4 border-red-600 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-6">
          <div className="text-center md:text-left">
            <h1 className="text-3xl md:text-4xl font-comic uppercase italic tracking-tighter leading-none">{UI_TEXT.TITLE}</h1>
            <p className="text-red-500 font-bold text-xs tracking-[0.2em] uppercase mt-1">{UI_TEXT.SUBTITLE}</p>
          </div>

          <div className="flex flex-wrap items-center justify-center gap-6">
            <div className="flex bg-gray-800 p-1 comic-border border-white border-2">
              <button onClick={() => setMode('gritty')} className={`px-4 py-1 text-xs font-bold uppercase ${mode === 'gritty' ? 'bg-white text-black' : 'text-gray-400'}`}>Gritty Noir</button>
              <button onClick={() => setMode('superhero')} className={`px-4 py-1 text-xs font-bold uppercase ${mode === 'superhero' ? 'bg-red-600 text-white' : 'text-gray-400'}`}>Heroic Fail</button>
            </div>

            <button onClick={() => setIsLockerOpen(true)} className="flex items-center gap-2 px-4 py-2 bg-gray-900 border-2 border-white hover:bg-gray-800 relative group" disabled={isLoadingAny}>
              <span className="text-xl">🗄️</span>
              <span className="text-[10px] font-bold uppercase hidden md:inline">{UI_TEXT.BUTTONS.VIEW_LOCKER}</span>
              {archive.length > 0 && (
                <span className="absolute -top-2 -right-2 bg-red-600 text-white text-[10px] w-5 h-5 rounded-full flex items-center justify-center border border-white font-bold">
                  {archive.length}
                </span>
              )}
            </button>

            <button onClick={handleOpenKeySelector} className="p-2 hover:bg-gray-800 rounded-full" disabled={isLoadingAny}><span className="text-2xl">🔑</span></button>

            {!isAppInitialized && (
              <button 
                onClick={() => setIsAppInitialized(true)}
                className={`px-8 py-3 font-comic text-xl uppercase tracking-wider bg-red-600 hover:bg-red-500 text-white comic-border border-white`}
              >
                {UI_TEXT.BUTTONS.NEW_CASE}
              </button>
            )}
          </div>
        </div>
      </header>

      <ArchiveLocker isOpen={isLockerOpen} onClose={() => setIsLockerOpen(false)} comics={archive} onSelect={selectArchivedComic} />

      <main className="max-w-7xl mx-auto px-4 mt-8">
        {!isAppInitialized && (
          <div className="flex flex-col items-center justify-center min-h-[60vh] text-center p-8 bg-white comic-border mt-12 relative overflow-hidden">
            <div className="text-8xl mb-6">{mode === 'gritty' ? '📁' : '🦸‍♂️'}</div>
            <h2 className="text-4xl font-comic uppercase mb-4 italic">{mode === 'gritty' ? UI_TEXT.LANDING.GRITTY.TITLE : UI_TEXT.LANDING.SUPERHERO.TITLE}</h2>
            <div className="max-w-xl text-gray-700 font-bold mb-8">
              {mode === 'gritty' ? UI_TEXT.LANDING.GRITTY.DESCRIPTION : UI_TEXT.LANDING.SUPERHERO.DESCRIPTION}
            </div>
            <div className="flex gap-4">
              <button onClick={() => setIsAppInitialized(true)} className="px-12 py-4 bg-red-600 text-white font-comic text-2xl uppercase hover:bg-red-700 comic-border border-white">{UI_TEXT.LANDING.BUTTON}</button>
              {archive.length > 0 && <button onClick={() => setIsLockerOpen(true)} className="px-8 py-4 bg-black text-white font-comic text-2xl uppercase hover:bg-gray-900 comic-border border-white">History</button>}
            </div>
          </div>
        )}

        {isAppInitialized && (
          <>
            <ReportListAndDetail
              mode={mode}
              availableReports={availableReports}
              selectedReport={selectedReport}
              onSelectReport={handleSelectReport}
              onBackToList={handleBackToList}
              onFetchNewReportList={handleGenerateReportList}
              onGenerateComicFromReport={generateComicStrip}
              isFetchingReportList={isFetchingReportList}
              isFetchingReportDetails={isFetchingReportDetails} // Pass new loading state
              isGeneratingComic={isGeneratingComic}
              error={error}
              currentLoadingPhase={currentLoadingPhase}
            />

            {error && !isLoadingAny && (
              <div className="p-8 bg-red-100 border-4 border-red-600 text-red-700 font-bold max-w-2xl mx-auto mt-12 text-center shadow-lg">
                <h3 className="text-2xl font-comic uppercase mb-2">
